"""Registry root and index schema regression tests (fixtures generated by xila-package)."""

import copy
import json
import unittest
from pathlib import Path

from jsonschema import Draft202012Validator

ROOT = Path(__file__).resolve().parents[1]


def load(name):
    return json.loads((ROOT / name).read_text(encoding="utf-8"))


ROOT_VALIDATOR = Draft202012Validator(load("schemas/registry-root.schema.json"))
INDEX_VALIDATOR = Draft202012Validator(load("schemas/registry-index.schema.json"))
ROOT_FIXTURE = load("tests/fixtures/registry-root.json")
INDEX_FIXTURE = load("tests/fixtures/registry-index.json")


class RegistryTrustSchemaTests(unittest.TestCase):
    def test_accepts_generated_documents(self):
        for validator in (ROOT_VALIDATOR, INDEX_VALIDATOR):
            Draft202012Validator.check_schema(validator.schema)
        ROOT_VALIDATOR.validate(ROOT_FIXTURE)
        INDEX_VALIDATOR.validate(INDEX_FIXTURE)

    def test_rejects_invalid_roots(self):
        for change in [
            lambda r: r.update(version=0),
            lambda r: r.update(root_keys=[]),
            lambda r: r["repository_keys"][0].update(public_key="AAAA"),
            lambda r: r["root_keys"][0].update(id="Root"),
            lambda r: r.update(extra=True),
        ]:
            broken = copy.deepcopy(ROOT_FIXTURE)
            change(broken)
            self.assertFalse(ROOT_VALIDATOR.is_valid(broken), broken)

    def test_rejects_invalid_indexes(self):
        for change in [
            lambda i: i.update(version=0),
            lambda i: i["files"][0].update(path="root.json"),
            lambda i: i["files"][0].update(path="packages/../keys/x.json"),
            lambda i: i["files"][0].update(sha256="A" * 64),
            lambda i: i["files"][0].update(size=0),
        ]:
            broken = copy.deepcopy(INDEX_FIXTURE)
            change(broken)
            self.assertFalse(INDEX_VALIDATOR.is_valid(broken), broken)


if __name__ == "__main__":
    unittest.main()
